@@ -1,0 +1,617 @@
+:root {
+  --bg: #faf8f5;
+  --surface: #ffffff;
+  --ink: #1a1a1a;
+  --ink-soft: #4a4a4a;
+  --muted: #6b6b6b;
+  --line: #e7e3dd;
+  --accent: #b6533c;       /* terracotta */
+  --accent-ink: #7a3526;
+  --sage: #8a9a82;
+  --sand: #e9e2d4;
+  --sky: #c9d6df;
+  --plum: #6b5876;
+  --focus: #2b6cb0;
+  --radius: 14px;
+  --radius-lg: 22px;
+  --shadow-sm: 0 1px 2px rgba(20, 20, 20, .04), 0 2px 8px rgba(20, 20, 20, .04);
+  --shadow-md: 0 6px 20px rgba(20, 20, 20, .08);
+  --max: 1240px;
+  --gutter: clamp(16px, 3vw, 32px);
+  --font-sans: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
+  --font-serif: "Fraunces", "Cormorant Garamond", Georgia, "Times New Roman", serif;
+}
+
+* { box-sizing: border-box; }
+
+html { scroll-behavior: smooth; }
+
+@media (prefers-reduced-motion: reduce) {
+  html { scroll-behavior: auto; }
+  *, *::before, *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }
+}
+
+body {
+  margin: 0;
+  font-family: var(--font-sans);
+  font-size: 16px;
+  line-height: 1.55;
+  color: var(--ink);
+  background: var(--bg);
+  -webkit-font-smoothing: antialiased;
+}
+
+img, svg { display: block; max-width: 100%; }
+
+a { color: inherit; }
+
+h1, h2, h3 { font-family: var(--font-serif); font-weight: 500; letter-spacing: -.01em; line-height: 1.15; margin: 0; }
+h2 { font-size: clamp(1.6rem, 2.6vw, 2.25rem); }
+h3 { font-size: 1.15rem; font-family: var(--font-sans); font-weight: 600; letter-spacing: 0; }
+
+p { margin: 0; }
+
+.visually-hidden {
+  position: absolute !important;
+  width: 1px; height: 1px;
+  padding: 0; margin: -1px;
+  overflow: hidden; clip: rect(0, 0, 0, 0);
+  white-space: nowrap; border: 0;
+}
+
+/* Focus */
+:focus-visible {
+  outline: 2px solid var(--focus);
+  outline-offset: 2px;
+  border-radius: 4px;
+}
+
+.skip-link {
+  position: absolute;
+  left: 12px; top: -40px;
+  background: var(--ink); color: #fff;
+  padding: 8px 14px; border-radius: 8px;
+  text-decoration: none; z-index: 1000;
+}
+.skip-link:focus { top: 12px; }
+
+/* Announcement bar */
+.announcement {
+  background: var(--ink);
+  color: #f5f1ea;
+  text-align: center;
+  font-size: .85rem;
+  padding: 10px var(--gutter);
+}
+
+/* Header */
+.site-header {
+  position: sticky; top: 0; z-index: 50;
+  background: rgba(250, 248, 245, .9);
+  backdrop-filter: saturate(140%) blur(10px);
+  border-bottom: 1px solid var(--line);
+}
+.site-header__inner {
+  max-width: var(--max);
+  margin: 0 auto;
+  padding: 14px var(--gutter);
+  display: grid;
+  grid-template-columns: auto 1fr auto;
+  gap: 24px;
+  align-items: center;
+}
+.brand {
+  display: inline-flex; align-items: center; gap: 10px;
+  text-decoration: none; color: var(--ink);
+}
+.brand__mark {
+  display: inline-grid; place-items: center;
+  width: 34px; height: 34px;
+  background: var(--ink); color: #faf8f5;
+  border-radius: 8px;
+  font-family: var(--font-serif); font-weight: 600; font-size: 18px;
+}
+.brand__name { font-family: var(--font-serif); font-size: 1.25rem; }
+
+.primary-nav ul {
+  display: flex; gap: 28px; list-style: none; padding: 0; margin: 0;
+  justify-content: center;
+}
+.primary-nav a {
+  text-decoration: none; color: var(--ink-soft);
+  font-size: .95rem; font-weight: 500;
+  padding: 6px 2px;
+  border-bottom: 1.5px solid transparent;
+  transition: color .15s, border-color .15s;
+}
+.primary-nav a:hover { color: var(--ink); border-color: var(--ink); }
+
+.header-actions { display: flex; align-items: center; gap: 6px; }
+
+.search {
+  display: flex; align-items: center;
+  background: var(--surface);
+  border: 1px solid var(--line);
+  border-radius: 999px;
+  padding: 4px 4px 4px 14px;
+  width: 240px;
+}
+.search:focus-within { border-color: var(--ink); }
+.search input {
+  border: 0; outline: none; background: transparent;
+  flex: 1; font: inherit; font-size: .9rem; color: var(--ink);
+  min-width: 0; padding: 6px 0;
+}
+.search button {
+  border: 0; background: var(--ink); color: #faf8f5;
+  width: 30px; height: 30px; border-radius: 999px;
+  display: grid; place-items: center; cursor: pointer;
+}
+
+.icon-btn {
+  position: relative;
+  border: 0; background: transparent; color: var(--ink);
+  width: 40px; height: 40px; border-radius: 999px;
+  display: grid; place-items: center; cursor: pointer;
+}
+.icon-btn:hover { background: var(--sand); }
+.cart-badge {
+  position: absolute; top: 4px; right: 4px;
+  min-width: 18px; height: 18px; padding: 0 5px;
+  background: var(--accent); color: #fff;
+  border-radius: 999px; font-size: 11px; font-weight: 600;
+  display: grid; place-items: center;
+}
+
+/* Buttons */
+.btn {
+  display: inline-flex; align-items: center; justify-content: center;
+  padding: 12px 22px;
+  font: inherit; font-weight: 500; font-size: .95rem;
+  border-radius: 999px; border: 1.5px solid transparent;
+  text-decoration: none; cursor: pointer;
+  transition: transform .12s ease, background .15s, color .15s, border-color .15s;
+  min-height: 44px;
+}
+.btn:active { transform: translateY(1px); }
+.btn--primary { background: var(--ink); color: #faf8f5; }
+.btn--primary:hover { background: #000; }
+.btn--ghost { background: transparent; color: var(--ink); border-color: var(--ink); }
+.btn--ghost:hover { background: var(--ink); color: #faf8f5; }
+
+/* Sections */
+main > section {
+  max-width: var(--max);
+  margin: 0 auto;
+  padding: clamp(48px, 7vw, 96px) var(--gutter);
+}
+.section-head {
+  display: flex; align-items: end; justify-content: space-between;
+  gap: 24px; margin-bottom: 32px; flex-wrap: wrap;
+}
+.section-link {
+  text-decoration: none; color: var(--ink);
+  font-weight: 500; font-size: .95rem;
+  border-bottom: 1.5px solid var(--ink);
+  padding-bottom: 2px;
+}
+.eyebrow {
+  font-size: .75rem; letter-spacing: .14em; text-transform: uppercase;
+  color: var(--muted); font-weight: 600; margin-bottom: 8px;
+}
+.eyebrow--accent { color: var(--accent); }
+
+/* HERO */
+.hero {
+  display: grid;
+  grid-template-columns: 1.05fr 1fr;
+  gap: clamp(24px, 4vw, 64px);
+  align-items: center;
+  padding-top: clamp(40px, 6vw, 80px) !important;
+  padding-bottom: clamp(40px, 6vw, 80px) !important;
+}
+.hero__content h2 {
+  font-size: clamp(2.2rem, 5vw, 4rem);
+  margin-top: 8px;
+}
+.hero__lede {
+  margin-top: 18px; max-width: 50ch;
+  color: var(--ink-soft); font-size: 1.05rem;
+}
+.hero__cta { display: flex; gap: 12px; margin-top: 28px; flex-wrap: wrap; }
+
+.hero__visual {
+  display: grid;
+  grid-template-columns: 1.2fr 1fr;
+  grid-template-rows: 1fr 1fr;
+  gap: 14px;
+  height: clamp(360px, 46vw, 540px);
+}
+.hero__panel {
+  border-radius: var(--radius-lg);
+  position: relative; overflow: hidden;
+}
+.hero__panel--a {
+  grid-row: 1 / span 2;
+  background:
+    radial-gradient(ellipse at 30% 70%, #d4b59a 0%, #b58a6b 60%, #8a614a 100%);
+}
+.hero__panel--a::after {
+  content: ""; position: absolute; inset: 0;
+  background:
+    radial-gradient(circle at 60% 55%, rgba(255,255,255,.25), transparent 40%),
+    radial-gradient(ellipse at 50% 90%, rgba(0,0,0,.2), transparent 50%);
+}
+.hero__panel--b {
+  background: linear-gradient(140deg, var(--sage) 0%, #6f8167 100%);
+}
+.hero__panel--b::after {
+  content: ""; position: absolute; inset: 0;
+  background: radial-gradient(circle at 70% 30%, rgba(255,255,255,.2), transparent 50%);
+}
+.hero__panel--c {
+  background: linear-gradient(140deg, var(--sand) 0%, #d6c9b0 100%);
+}
+.hero__panel--c::after {
+  content: ""; position: absolute; inset: 0;
+  background:
+    repeating-linear-gradient(45deg, transparent 0 14px, rgba(122, 90, 60, .12) 14px 16px);
+}
+
+/* CATEGORIES */
+.cat-grid {
+  list-style: none; padding: 0; margin: 0;
+  display: grid;
+  grid-template-columns: repeat(6, 1fr);
+  gap: 16px;
+}
+.cat-grid a {
+  display: flex; flex-direction: column; align-items: center; gap: 12px;
+  text-decoration: none; color: var(--ink);
+  font-weight: 500; font-size: .95rem;
+  padding: 12px; border-radius: var(--radius);
+  transition: background .15s;
+}
+.cat-grid a:hover { background: var(--surface); }
+.cat-thumb {
+  width: 100%; aspect-ratio: 1 / 1;
+  border-radius: 50%;
+  background: var(--surface);
+  border: 1px solid var(--line);
+  position: relative; overflow: hidden;
+}
+.cat-thumb--kitchen   { background: radial-gradient(circle at 50% 60%, #efe6d6, #d2c4a8); }
+.cat-thumb--textiles  { background: radial-gradient(circle at 50% 60%, #e3d3d8, #b89aa1); }
+.cat-thumb--bath      { background: radial-gradient(circle at 50% 60%, #d6e2e6, #94b1bd); }
+.cat-thumb--lighting  { background: radial-gradient(circle at 50% 40%, #fff3d6, #d8b86a); }
+.cat-thumb--decor     { background: radial-gradient(circle at 50% 60%, #e6e0d2, #a89c7a); }
+.cat-thumb--outdoor   { background: radial-gradient(circle at 50% 60%, #d8e3d4, #7f9576); }
+
+/* PRODUCTS */
+.product-grid {
+  list-style: none; padding: 0; margin: 0;
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 24px;
+}
+.product-card {
+  background: var(--surface);
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex; flex-direction: column;
+  border: 1px solid var(--line);
+  transition: transform .2s ease, box-shadow .2s ease, border-color .2s;
+}
+.product-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); border-color: transparent; }
+.product-card__media {
+  aspect-ratio: 4 / 5;
+  position: relative;
+  overflow: hidden;
+}
+.product-card__badge {
+  position: absolute; top: 12px; left: 12px;
+  background: #fff; color: var(--ink);
+  font-size: .72rem; font-weight: 600;
+  padding: 5px 10px; border-radius: 999px;
+  letter-spacing: .04em; text-transform: uppercase;
+}
+.product-card__badge--sale { background: var(--accent); color: #fff; }
+.product-card__badge--new { background: var(--ink); color: #fff; }
+.product-card__fav {
+  position: absolute; top: 10px; right: 10px;
+  width: 36px; height: 36px; border-radius: 999px;
+  border: 0; background: rgba(255,255,255,.92);
+  display: grid; place-items: center; cursor: pointer;
+  color: var(--ink);
+}
+.product-card__fav:hover { background: #fff; }
+.product-card__fav[aria-pressed="true"] { color: var(--accent); }
+
+.product-card__body {
+  padding: 16px 16px 18px;
+  display: flex; flex-direction: column; gap: 6px; flex: 1;
+}
+.product-card__cat {
+  font-size: .72rem; letter-spacing: .12em; text-transform: uppercase;
+  color: var(--muted); font-weight: 600;
+}
+.product-card__title {
+  font-size: 1rem; font-weight: 500; color: var(--ink);
+  text-decoration: none;
+}
+.product-card__title::after { content: ""; position: absolute; inset: 0; }
+.product-card__title-wrap { position: relative; }
+.product-card__price {
+  margin-top: 6px;
+  display: flex; align-items: baseline; gap: 8px;
+  font-weight: 600;
+}
+.product-card__price del { color: var(--muted); font-weight: 400; font-size: .9em; }
+.product-card__price .sale { color: var(--accent); }
+
+.product-card__rating {
+  display: flex; align-items: center; gap: 6px;
+  font-size: .82rem; color: var(--muted);
+}
+.stars { color: #d4a23a; letter-spacing: 1px; }
+
+.product-card__add {
+  margin-top: 12px;
+  border: 1px solid var(--ink); background: transparent; color: var(--ink);
+  padding: 10px 14px; border-radius: 999px;
+  font: inherit; font-weight: 500; font-size: .9rem;
+  cursor: pointer; min-height: 40px;
+  position: relative; z-index: 1;
+  transition: background .15s, color .15s;
+}
+.product-card__add:hover { background: var(--ink); color: #faf8f5; }
+
+/* Product card image swatches (stylized) */
+.pm { width: 100%; height: 100%; position: relative; }
+.pm--1 { background: linear-gradient(160deg, #efe6d6, #c8b491); }
+.pm--2 { background: linear-gradient(160deg, #d6e2e6, #92aab6); }
+.pm--3 { background: linear-gradient(160deg, #e6dcd0, #ad9277); }
+.pm--4 { background: linear-gradient(160deg, #d9d2c2, #948a72); }
+.pm--5 { background: linear-gradient(160deg, #efd9d2, #be8e84); }
+.pm--6 { background: linear-gradient(160deg, #dde6d4, #8ba47e); }
+.pm--7 { background: linear-gradient(160deg, #f1ecdf, #c8b88a); }
+.pm--8 { background: linear-gradient(160deg, #e2d6e0, #9c84a3); }
+.pm::after {
+  content: ""; position: absolute; inset: 0;
+  background:
+    radial-gradient(circle at 40% 45%, rgba(255,255,255,.35), transparent 35%),
+    radial-gradient(ellipse at 60% 85%, rgba(0,0,0,.18), transparent 55%);
+}
+.pm--shape::before {
+  content: ""; position: absolute;
+  left: 50%; top: 55%; transform: translate(-50%, -50%);
+  width: 56%; aspect-ratio: 1 / 1;
+  background: rgba(255, 255, 255, .55);
+  border-radius: 50%;
+  filter: blur(.3px);
+  box-shadow: inset 0 -10px 20px rgba(0,0,0,.08);
+}
+.pm--cup::before {
+  content: ""; position: absolute;
+  left: 50%; top: 55%; transform: translate(-50%, -50%);
+  width: 44%; aspect-ratio: 1 / 1.1;
+  background: rgba(255,255,255,.65);
+  border-radius: 8px 8px 40px 40px / 8px 8px 30px 30px;
+}
+.pm--bottle::before {
+  content: ""; position: absolute;
+  left: 50%; top: 50%; transform: translate(-50%, -50%);
+  width: 22%; height: 70%;
+  background: rgba(255,255,255,.6);
+  border-radius: 16px 16px 24px 24px / 30px 30px 24px 24px;
+  box-shadow: inset -6px 0 12px rgba(0,0,0,.1);
+}
+.pm--plate::before {
+  content: ""; position: absolute;
+  left: 50%; top: 55%; transform: translate(-50%, -50%);
+  width: 68%; aspect-ratio: 1 / 1;
+  background: rgba(255,255,255,.55);
+  border-radius: 50%;
+  border: 6px solid rgba(255,255,255,.35);
+}
+
+/* DEALS */
+.deals { background: linear-gradient(180deg, transparent, #f4ede2 25%, #f4ede2 75%, transparent); }
+.countdown {
+  font-family: var(--font-sans);
+  font-variant-numeric: tabular-nums;
+  font-weight: 600; color: var(--accent-ink);
+  background: #fff; border: 1px solid var(--line);
+  padding: 10px 16px; border-radius: 999px;
+  font-size: .95rem;
+}
+
+/* EDITORIAL */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr 1fr;
+  gap: 24px;
+}
+.editorial-card {
+  background: var(--surface);
+  border-radius: var(--radius);
+  overflow: hidden;
+  border: 1px solid var(--line);
+  transition: transform .2s, box-shadow .2s;
+}
+.editorial-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
+.editorial-card__link { display: flex; flex-direction: column; height: 100%; text-decoration: none; color: var(--ink); }
+.editorial-card__media { aspect-ratio: 4 / 3; }
+.editorial-card--feature .editorial-card__media { aspect-ratio: 5 / 6; }
+.editorial-card--feature { grid-row: span 2; }
+.editorial-card__media--feature {
+  background:
+    radial-gradient(circle at 30% 30%, #f3d7a0, transparent 50%),
+    linear-gradient(160deg, #b6533c, #7a3526);
+}
+.editorial-card__media--two {
+  background: linear-gradient(160deg, #c9d6df, #6b8693);
+}
+.editorial-card__media--three {
+  background: linear-gradient(160deg, #d8c8b6, #9a7e60);
+}
+.editorial-card__body { padding: 22px 22px 26px; }
+.editorial-card__kicker {
+  font-size: .75rem; letter-spacing: .12em; text-transform: uppercase;
+  color: var(--muted); font-weight: 600; margin-bottom: 10px;
+}
+.editorial-card h3 {
+  font-family: var(--font-serif); font-weight: 500;
+  font-size: 1.25rem; line-height: 1.3;
+  margin-bottom: 8px;
+}
+.editorial-card--feature h3 { font-size: clamp(1.4rem, 2.2vw, 1.9rem); }
+.editorial-card p { color: var(--ink-soft); font-size: .95rem; }
+
+/* TRUST */
+.trust { padding-top: 0 !important; padding-bottom: clamp(48px, 6vw, 80px) !important; }
+.trust ul {
+  list-style: none; padding: 28px clamp(20px, 3vw, 40px); margin: 0;
+  display: grid; grid-template-columns: repeat(4, 1fr); gap: 18px;
+  background: var(--surface);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+}
+.trust li {
+  display: flex; align-items: center; gap: 14px;
+  color: var(--ink);
+}
+.trust li + li { border-left: 1px solid var(--line); padding-left: 18px; }
+.trust strong { display: block; font-size: .95rem; font-weight: 600; }
+.trust span { font-size: .82rem; color: var(--muted); }
+
+/* NEWSLETTER */
+.newsletter {
+  padding-top: 0 !important;
+}
+.newsletter__inner {
+  background: var(--ink);
+  color: #f5f1ea;
+  border-radius: var(--radius-lg);
+  padding: clamp(36px, 5vw, 64px);
+  display: grid;
+  grid-template-columns: 1.1fr 1fr;
+  gap: clamp(24px, 4vw, 64px);
+  align-items: center;
+}
+.newsletter h2 { color: #fff; margin: 6px 0 10px; }
+.newsletter .eyebrow { color: #c9b8a4; }
+.newsletter p { color: #d8d2c8; }
+.newsletter__form {
+  display: grid; grid-template-columns: 1fr auto; gap: 10px;
+  position: relative;
+}
+.newsletter__form input {
+  font: inherit; font-size: 1rem;
+  padding: 14px 18px;
+  border-radius: 999px; border: 1px solid #4a4540;
+  background: #2a2723; color: #fff;
+  min-height: 48px;
+}
+.newsletter__form input::placeholder { color: #9a938b; }
+.newsletter__form input:focus { outline: 2px solid #fff; outline-offset: 2px; border-color: #fff; }
+.newsletter__form .btn--primary {
+  background: #faf8f5; color: var(--ink);
+}
+.newsletter__form .btn--primary:hover { background: #fff; }
+.form-msg {
+  grid-column: 1 / -1;
+  font-size: .85rem; min-height: 1.2em; color: #c9b8a4;
+}
+.form-msg.is-error { color: #f1a89a; }
+.form-msg.is-ok { color: #b8d8a8; }
+
+/* FOOTER */
+.site-footer {
+  border-top: 1px solid var(--line);
+  background: var(--bg);
+  padding: 56px var(--gutter) 24px;
