/* EDITORIAL */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 24px;
}
.editorial-card {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--line);
  transition: transform .2s, box-shadow .2s;
}
.editorial-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.editorial-card__link { display: flex; flex-direction: column; height: 100%; text-decoration: none; color: var(--ink); }
.editorial-card__media { aspect-ratio: 4 / 3; }
.editorial-card--feature .editorial-card__media { aspect-ratio: 5 / 6; }
.editorial-card--feature { grid-row: span 2; }
.editorial-card__media--feature {
  background:
    radial-gradient(circle at 30% 30%, #f3d7a0, transparent 50%),
    linear-gradient(160deg, #b6533c, #7a3526);
}
.editorial-card__media--two {
  background: linear-gradient(160deg, #c9d6df, #6b8693);
}
.editorial-card__media--three {
  background: linear-gradient(160deg, #d8c8b6, #9a7e60);
}
.editorial-card__body { padding: 22px 22px 26px; }
.editorial-card__kicker {
  font-size: .75rem; letter-spacing: .12em; text-transform: uppercase;
  color: var(--muted); font-weight: 600; margin-bottom: 10px;
}
.editorial-card h3 {
  font-family: var(--font-serif); font-weight: 500;
  font-size: 1.25rem; line-height: 1.3;
  margin-bottom: 8px;
}
.editorial-card--feature h3 { font-size: clamp(1.4rem, 2.2vw, 1.9rem); }
.editorial-card p { color: var(--ink-soft); font-size: .95rem; }

/* TRUST */
.trust { padding-top: 0 !important; padding-bottom: clamp(48px, 6vw, 80px) !important; }
.trust ul {
  list-style: none; padding: 28px clamp(20px, 3vw, 40px); margin: 0;
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 18px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}
.trust li {
  display: flex; align-items: center; gap: 14px;
  color: var(--ink);
}
.trust li + li { border-left: 1px solid var(--line); padding-left: 18px; }
.trust strong { display: block; font-size: .95rem; font-weight: 600; }
.trust span { font-size: .82rem; color: var(--muted); }

/* NEWSLETTER */
.newsletter {
  padding-top: 0 !important;
}
.newsletter__inner {
  background: var(--ink);
  color: #f5f1ea;
  border-radius: var(--radius-lg);
  padding: clamp(36px, 5vw, 64px);
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: clamp(24px, 4vw, 64px);
  align-items: center;
}
.newsletter h2 { color: #fff; margin: 6px 0 10px; }
.newsletter .eyebrow { color: #c9b8a4; }
.newsletter p { color: #d8d2c8; }
.newsletter__form {
  display: grid; grid-template-columns: 1fr auto; gap: 10px;
  position: relative;
}
.newsletter__form input {
  font: inherit; font-size: 1rem;
  padding: 14px 18px;
  border-radius: 999px; border: 1px solid #4a4540;
  background: #2a2723; color: #fff;
  min-height: 48px;
}
.newsletter__form input::placeholder { color: #9a938b; }
.newsletter__form input:focus { outline: 2px solid #fff; outline-offset: 2px; border-color: #fff; }
.newsletter__form .btn--primary {
  background: #faf8f5; color: var(--ink);
}
.newsletter__form .btn--primary:hover { background: #fff; }
.form-msg {
  grid-column: 1 / -1;
  font-size: .85rem; min-height: 1.2em; color: #c9b8a4;
}
.form-msg.is-error { color: #f1a89a; }
.form-msg.is-ok { color: #b8d8a8; }

/* FOOTER */
.site-footer {
  border-top: 1px solid var(--line);
  background: var(--bg);
  padding: 56px var(--gutter) 24px;
}
.site-footer__inner {
  max-width: var(--max);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.2fr 2fr;
  gap: 48px;
}
.site-footer__brand p { color: var(--muted); font-size: .9rem; margin-top: 14px; max-width: 32ch; }
.site-footer nav {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px;
}
.site-footer h2 {
  font-family: var(--font-sans);
  font-size: .8rem; letter-spacing: .14em; text-transform: uppercase;
  color: var(--ink); font-weight: 600; margin-bottom: 14px;
}
.site-footer ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.site-footer a { color: var(--ink-soft); text-decoration: none; font-size: .9rem; }
.site-footer a:hover { color: var(--ink); text-decoration: underline; }
.site-footer__legal {
  max-width: var(--max);
  margin: 40px auto 0;
  padding-top: 20px;
  border-top: 1px solid var(--line);
  display: flex; justify-content: space-between; flex-wrap: wrap; gap: 12px;
  font-size: .82rem; color: var(--muted);
}
.site-footer__legal ul { list-style: none; padding: 0; margin: 0; display: flex; gap: 18px; }

/* TOAST */
.toast {
  position: fixed; bottom: 24px; left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--ink); color: #fff;
  padding: 12px 18px; border-radius: 999px;
  font-size: .9rem; box-shadow: var(--shadow-md);
  opacity: 0; pointer-events: none;
  transition: opacity .2s ease, transform .2s ease;
  z-index: 100;
}
.toast.is-visible {
  opacity: 1; transform: translateX(-50%) translateY(0);
}

/* RESPONSIVE */
@media (max-width: 980px) {
  .primary-nav { display: none; }
  .site-header__inner { grid-template-columns: auto 1fr auto; }
  .search { width: 180px; }
  .hero { grid-template-columns: 1fr; }
  .hero__visual { height: clamp(280px, 60vw, 380px); }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .cat-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card--feature { grid-column: 1 / -1; grid-row: auto; }
  .editorial-card--feature .editorial-card__media { aspect-ratio: 16 / 9; }
  .trust ul { grid-template-columns: repeat(2, 1fr); }
  .trust li:nth-child(3) { border-left: 0; padding-left: 0; }
  .newsletter__inner { grid-template-columns: 1fr; }
  .site-footer__inner { grid-template-columns: 1fr; }
}

@media (max-width: 640px) {
  .search { display: none; }
  .header-actions { gap: 2px; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 14px; }
  .cat-grid { grid-template-columns: repeat(3, 1fr); gap: 10px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .trust ul { grid-template-columns: 1fr; padding: 16px; }
  .trust li + li { border-left: 0; padding-left: 0; border-top: 1px solid var(--line); padding-top: 14px; }
  .site-footer nav { grid-template-columns: 1fr 1fr; gap: 24px; }
  .section-head { margin-bottom: 22px; }
  .newsletter__form { grid-template-columns: 1fr; }
}

/* Forced colors */
@media (forced-colors: active) {
  .product-card, .editorial-card, .trust ul, .search, .cat-thumb, .hero__panel {
    border: 1px solid CanvasText;
  }
  .btn { border: 1px solid CanvasText; }
}
