  --font-serif: "Fraunces", "Cormorant Garamond", Georgia, "Times New Roman", serif;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }
}

body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

img, svg { display: block; max-width: 100%; }

a { color: inherit; }

h1, h2, h3 { font-family: var(--font-serif); font-weight: 500; letter-spacing: -.01em; line-height: 1.15; margin: 0; }
h2 { font-size: clamp(1.6rem, 2.6vw, 2.25rem); }
h3 { font-size: 1.15rem; font-family: var(--font-sans); font-weight: 600; letter-spacing: 0; }

p { margin: 0; }

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0);
  white-space: nowrap; border: 0;
}

/* Focus */
:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.skip-link {
  position: absolute;
  left: 12px; top: -40px;
  background: var(--ink); color: #fff;
  padding: 8px 14px; border-radius: 8px;
  text-decoration: none; z-index: 1000;
}
.skip-link:focus { top: 12px; }

/* Announcement bar */
.announcement {
  background: var(--ink);
  color: #f5f1ea;
  text-align: center;
  font-size: .85rem;
  padding: 10px var(--gutter);
}

/* Header */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(250, 248, 245, .9);
  backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--line);
}
.site-header__inner {
  max-width: var(--max);
  margin: 0 auto;
  padding: 14px var(--gutter);
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 24px;
  align-items: center;
}
.brand {
  display: inline-flex; align-items: center; gap: 10px;
  text-decoration: none; color: var(--ink);
}
.brand__mark {
  display: inline-grid; place-items: center;
  width: 34px; height: 34px;
  background: var(--ink); color: #faf8f5;
  border-radius: 8px;
  font-family: var(--font-serif); font-weight: 600; font-size: 18px;
}
.brand__name { font-family: var(--font-serif); font-size: 1.25rem; }

.primary-nav ul {
  display: flex; gap: 28px; list-style: none; padding: 0; margin: 0;
  justify-content: center;
}
.primary-nav a {
  text-decoration: none; color: var(--ink-soft);
  font-size: .95rem; font-weight: 500;
  padding: 6px 2px;
  border-bottom: 1.5px solid transparent;
  transition: color .15s, border-color .15s;
}
.primary-nav a:hover { color: var(--ink); border-color: var(--ink); }

.header-actions { display: flex; align-items: center; gap: 6px; }

.search {
  display: flex; align-items: center;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 4px 4px 4px 14px;
  width: 240px;
}
.search:focus-within { border-color: var(--ink); }
.search input {
  border: 0; outline: none; background: transparent;
  flex: 1; font: inherit; font-size: .9rem; color: var(--ink);
  min-width: 0; padding: 6px 0;
}
.search button {
  border: 0; background: var(--ink); color: #faf8f5;
  width: 30px; height: 30px; border-radius: 999px;
  display: grid; place-items: center; cursor: pointer;
}

.icon-btn {
  position: relative;
  border: 0; background: transparent; color: var(--ink);
  width: 40px; height: 40px; border-radius: 999px;
  display: grid; place-items: center; cursor: pointer;
}
.icon-btn:hover { background: var(--sand); }
