}
.hero__panel--c {
  background: linear-gradient(140deg, var(--sand) 0%, #d6c9b0 100%);
}
.hero__panel--c::after {
  content: ""; position: absolute; inset: 0;
  background:
    repeating-linear-gradient(45deg, transparent 0 14px, rgba(122, 90, 60, .12) 14px 16px);
}

/* CATEGORIES */
.cat-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}
.cat-grid a {
  display: flex; flex-direction: column; align-items: center; gap: 12px;
  text-decoration: none; color: var(--ink);
