.product-card__add:hover { background: var(--ink); color: #faf8f5; }

/* Product card image swatches (stylized) */
.pm { width: 100%; height: 100%; position: relative; }
.pm--1 { background: linear-gradient(160deg, #efe6d6, #c8b491); }
.pm--2 { background: linear-gradient(160deg, #d6e2e6, #92aab6); }
.pm--3 { background: linear-gradient(160deg, #e6dcd0, #ad9277); }
.pm--4 { background: linear-gradient(160deg, #d9d2c2, #948a72); }
.pm--5 { background: linear-gradient(160deg, #efd9d2, #be8e84); }
.pm--6 { background: linear-gradient(160deg, #dde6d4, #8ba47e); }
